// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"IB Math AA emphasizes algebraic reasoning and proof. We start with sequences, series and their applications.","blocks":[{"t":"key","text":"Arithmetic: uₙ = u₁ + (n − 1)d, Sₙ = (n/2)(2u₁ + (n − 1)d). Geometric: uₙ = u₁rⁿ⁻¹, Sₙ = u₁(1 − rⁿ)/(1 − r), and S∞ = u₁/(1 − r) when |r| < 1."},{"t":"p","text":"Sigma notation compactly writes sums. Financial applications use geometric growth: compound interest FV = PV(1 + r/(100k))^(kn), and the GDC's finance solver handles loans and annuities."},{"t":"ex","problem":"A geometric series has u₁ = 8 and r = 1/2. Find S∞.","steps":["|r| < 1, so it converges"],"answer":"S∞ = 8/(1 − 1/2) = 16"},{"t":"tip","text":"In Paper 1 (no calculator), simplify fractions and surds exactly. In Paper 2, use the GDC for heavy computation, but show your setup."},{"t":"lab","kind":"demo","title":"Paying off a car loan","aim":"Borrow money for a car at 6% a year, paid monthly. How do the payments and total interest depend on the loan length?","sets":[{"name":"yrs","start":5,"label":"Loan length (years)","min":1,"max":10,"step":1},{"name":"P","start":20000,"label":"Amount borrowed ($)","min":5000,"max":50000,"step":1000}],"outs":[{"name":"r","expr":"0.06/12","label":"Monthly rate"},{"name":"pay","expr":"P*r/(1 - (1 + r)^(-12*yrs))","label":"Monthly payment ($)"},{"name":"interest","expr":"pay*12*yrs - P","label":"Total interest ($)"}],"steps":["Compare a 3-year and a 7-year loan for $20,000."],"noise":0,"result":"The payment formula comes from the sum of a geometric series. Longer loans have smaller payments but much more total interest, which is the trade-off TVM solvers help you compare.","plot":{"x":"yrs","y":"interest"}}]},{"say":"Logarithms and the binomial theorem are core AA tools, and you'll write your own proofs.","blocks":[{"t":"key","text":"Laws of logs: log(xy) = log x + log y, log(x/y) = log x − log y, log xⁿ = n log x, change of base log_b x = ln x/ln b. Solve exponential equations by taking logs."},{"t":"p","text":"Binomial theorem: (a + b)ⁿ = Σ ⁿCᵣ aⁿ⁻ʳ bʳ, with ⁿCᵣ = n!/(r!(n − r)!)."},{"t":"p","text":"Proof: direct proof from definitions; proof by counterexample to disprove. HL adds proof by induction, contradiction, complex numbers and systems of equations."},{"t":"ex","problem":"Find the coefficient of x³ in (2 + x)⁵.","steps":["The term is ⁵C₃ · 2² · x³"],"answer":"10 × 4 = 40"}]}],[{"say":"Functions are the language of Math AA. You'll analyze them algebraically and graphically.","blocks":[{"t":"key","text":"Domain and range, composite functions (f ∘ g)(x) = f(g(x)), and inverse functions f⁻¹ (reflect in y = x; exists only if f is one-to-one)."},{"t":"p","text":"Transformations of y = f(x): f(x) + b shifts up, f(x − a) shifts right, pf(x) stretches vertically by p, f(qx) stretches horizontally by 1/q, −f(x) reflects in the x-axis, f(−x) reflects in the y-axis."},{"t":"ex","problem":"Describe y = 2f(x − 3) + 1 relative to y = f(x).","steps":["Horizontal shift right 3","Vertical stretch by 2, then shift up 1"],"answer":"Right 3, stretched vertically ×2, up 1"}]},{"say":"AA expects you to sketch and analyze key function families, finding intercepts, asymptotes and turning points.","blocks":[{"t":"key","text":"Quadratics: f(x) = a(x − h)² + k has vertex (h, k); the discriminant Δ = b² − 4ac gives the number of real roots."},{"t":"p","text":"Rational functions f(x) = (ax + b)/(cx + d) have vertical asymptote x = −d/c and horizontal asymptote y = a/c."},{"t":"p","text":"Exponential f(x) = aˣ has horizontal asymptote y = 0; logarithmic f(x) = logₐ x has vertical asymptote x = 0. They're inverses."},{"t":"ex","problem":"Find the asymptotes of f(x) = (2x + 1)/(x − 3).","steps":["Vertical: x = 3"],"answer":"Horizontal: y = 2/1 = 2"},{"t":"lab","kind":"demo","title":"Decibels and distance","aim":"Sound intensity from a speaker falls with distance. Loudness in decibels uses a logarithm: L = 10 log₁₀(I/10⁻¹²).","sets":[{"name":"d","start":10,"label":"Distance from the speaker (m)","min":1,"max":100,"step":1},{"name":"P","start":1,"label":"Speaker power (W)","min":0.01,"max":10,"step":0.01}],"outs":[{"name":"I","expr":"P/(4*pi*d^2)","label":"Intensity (W/m²)"},{"name":"L","expr":"10*log(I/1e-12)","label":"Loudness (dB)"}],"steps":["How many decibels do you lose each time you double your distance?"],"noise":0,"result":"Doubling the distance quarters the intensity, which is always a drop of about 6 dB, because log turns multiplication into subtraction: 10 log(1/4) ≈ −6.","plot":{"x":"d","y":"L"}}]}],[{"say":"Trigonometry in AA connects triangles, the unit circle and periodic functions.","blocks":[{"t":"key","text":"Sine rule: a/sin A = b/sin B = c/sin C (watch for the ambiguous case). Cosine rule: c² = a² + b² − 2ab cos C. Area = ½ab sin C."},{"t":"p","text":"Radians: arc length l = rθ, sector area A = ½r²θ."},{"t":"p","text":"Identities: sin²θ + cos²θ = 1, tan θ = sin θ/cos θ, double angle sin 2θ = 2 sin θ cos θ, cos 2θ = cos²θ − sin²θ."},{"t":"p","text":"Trig equations: find all solutions in the given domain using symmetry of the unit circle."},{"t":"ex","problem":"Solve 2 sin x = 1 for 0 ≤ x ≤ 2π.","steps":["sin x = 1/2"],"answer":"x = π/6 or 5π/6"}]},{"say":"AA also covers 3D shapes and graphs of trig functions. HL adds vectors.","blocks":[{"t":"key","text":"Volume and surface area of pyramids, cones and spheres; use Pythagoras and trig to find lengths and angles in 3D (for example, the angle between a line and a plane)."},{"t":"p","text":"Trig graphs: f(x) = a sin(b(x + c)) + d has amplitude |a|, period 2π/b, horizontal shift −c and principal axis y = d. These model periodic phenomena like tides."},{"t":"p","text":"HL extends to vectors (lines and planes in 3D, scalar and vector products) and complex numbers in polar form."},{"t":"ex","problem":"The depth of water is d(t) = 3 sin(πt/6) + 5 meters. Find the maximum depth and the period.","steps":["Maximum when sin = 1: 3 + 5"],"answer":"8 m; period 2π/(π/6) = 12 hours"},{"t":"lab","kind":"demo","title":"Will the pole fit in the box?","aim":"Find the longest straight pole that fits in a box, and the angle it makes with the base.","sets":[{"name":"a","start":60,"label":"Length (cm)","min":10,"max":120,"step":5},{"name":"b","start":40,"label":"Width (cm)","min":10,"max":100,"step":5},{"name":"c","start":30,"label":"Height (cm)","min":10,"max":100,"step":5}],"outs":[{"name":"base","expr":"sqrt(a^2 + b^2)","label":"Base diagonal (cm)"},{"name":"d","expr":"sqrt(a^2 + b^2 + c^2)","label":"Space diagonal (cm)"},{"name":"ang","expr":"atand(c/base)","label":"Angle with the base (°)"}],"steps":["Use Pythagoras twice: first across the base, then up to the opposite corner."],"noise":0,"result":"The space diagonal is √(a² + b² + c²). The angle between it and the base comes from the right triangle formed by the base diagonal and the height: tan θ = c/√(a² + b²).","plot":{"x":"c","y":"d"}}]}],[{"say":"Statistics in AA covers describing data and modeling relationships. The GDC does much of the computation.","blocks":[{"t":"key","text":"Measures of center (mean, median, mode) and spread (range, IQR, standard deviation). Outliers lie beyond Q1 − 1.5·IQR or Q3 + 1.5·IQR."},{"t":"p","text":"Bivariate data: Pearson's correlation coefficient r measures linear correlation. The regression line of y on x predicts y from x; use it only within the data range (interpolation). AA also uses the regression line of x on y."},{"t":"p","text":"Sampling: random, systematic, stratified, quota and convenience sampling, with possible bias."},{"t":"ex","problem":"r = −0.92 between hours of screen time and sleep. Interpret.","steps":["Strong negative linear correlation"],"answer":"More screen time is associated with less sleep (not necessarily caused by it)"}]},{"say":"Probability and distributions let you model uncertainty, from coin tosses to test scores.","blocks":[{"t":"key","text":"Venn diagrams and tree diagrams organize outcomes. P(A ∪ B) = P(A) + P(B) − P(A ∩ B). Conditional probability P(A | B) = P(A ∩ B)/P(B). Independent: P(A ∩ B) = P(A)P(B)."},{"t":"p","text":"Discrete random variables: E(X) = Σ x P(X = x). Binomial distribution X ~ B(n, p): mean np. Normal distribution X ~ N(μ, σ²): use the GDC for probabilities and inverse normal."},{"t":"ex","problem":"X ~ B(10, 0.3). Find E(X).","steps":["E(X) = np"],"answer":"3"},{"t":"lab","kind":"demo","title":"Quality control on bolts","aim":"Bolts must be 10.0 ± 0.2 mm. Lengths are normal with the machine's mean and standard deviation.","sets":[{"name":"sd","start":0.1,"label":"Standard deviation (mm)","min":0.02,"max":0.3,"step":0.01},{"name":"mu","start":10,"label":"Machine mean (mm)","min":9.8,"max":10.2,"step":0.01}],"outs":[{"name":"ok","expr":"100*(normcdf((10.2 - mu)/sd) - normcdf((9.8 - mu)/sd))","label":"Within tolerance (%)"}],"steps":["What standard deviation keeps 99% of bolts in tolerance when the mean is exactly 10.0?"],"noise":0,"result":"P(9.8 < X < 10.2) uses the normal CDF. With σ = 0.1 mm about 95% pass; you need σ ≈ 0.078 mm for 99%. A mean that drifts off-center lowers the pass rate quickly.","plot":{"x":"sd","y":"ok"}}]}],[{"say":"Calculus is the heart of Math AA. Derivatives measure rates of change and find optimal values.","blocks":[{"t":"key","text":"f′(x) = lim (h→0) [f(x + h) − f(x)]/h. Rules: power, product, quotient and chain rules; derivatives of eˣ, ln x, sin x and cos x."},{"t":"p","text":"Applications: tangents and normals, increasing and decreasing intervals, stationary points (f′ = 0), the second derivative test (f″ > 0 minimum, f″ < 0 maximum), points of inflection, and optimization."},{"t":"ex","problem":"Find the gradient of the normal to y = x² at x = 3.","steps":["Gradient of tangent: 2x = 6"],"answer":"Normal gradient: −1/6"},{"t":"p","text":"HL adds implicit differentiation, related rates, L'Hôpital's rule and more."}]},{"say":"Integration accumulates change: areas, volumes and distances. Kinematics ties it all together.","blocks":[{"t":"key","text":"Indefinite integrals: ∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C, ∫ eˣ dx = eˣ + C, ∫ 1/x dx = ln|x| + C, ∫ sin x dx = −cos x + C. Definite integrals give areas; area between curves = ∫(top − bottom) dx."},{"t":"p","text":"Substitution reverses the chain rule. Kinematics: v = ds/dt, a = dv/dt; displacement = ∫v dt; total distance = ∫|v| dt."},{"t":"p","text":"HL adds integration by parts, volumes of revolution and differential equations."},{"t":"ex","problem":"Find the area under y = 3x² from x = 0 to 2.","steps":["∫₀² 3x² dx = [x³] from 0 to 2"],"answer":"8"},{"t":"p","text":"Internal assessment: the mathematical exploration is a 12–20 page investigation of a topic you choose, worth 20% of your grade."},{"t":"lab","kind":"demo","title":"A particle on a track","aim":"A particle moves with velocity v(t) = 6t − t² m/s, starting at the origin. Find its displacement by integrating.","sets":[{"name":"t","start":3,"label":"Time (s)","min":0,"max":9,"step":0.1}],"outs":[{"name":"v","expr":"6*t - t^2","label":"Velocity (m/s)"},{"name":"s","expr":"3*t^2 - t^3/3","label":"Displacement (m)"},{"name":"dist","expr":"if(t > 6, 36 + (36 - s), s)","label":"Total distance (m)"}],"steps":["When does the particle turn around? Compare displacement and total distance at t = 9."],"noise":0,"result":"Displacement s = ∫v dt = 3t² − t³/3. The particle turns at t = 6 (v = 0); after that it moves back, so distance traveled exceeds displacement: at t = 9, s = 0 but the distance is 72 m.","plot":{"x":"t","y":"s"}}]}]];
export default text;
